(()=>{let meta,busy=false;const form=document.querySelector('form'),out=document.querySelector('#result');
async function req(path,body){meta||=await(await fetch('/api/meta')).json();const r=await fetch('/api/director/'+path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-ScoreDeck-Key':meta.controlKey,'X-ScoreDeck-Epoch':meta.serverEpoch,'X-ScoreDeck-Control-Epoch':meta.controlEpoch},...(body===undefined?{}:{body:JSON.stringify(body)})});const d=await r.json();if(!r.ok)throw Error(d.error||'请求失败');return d;}
async function action(fn){if(busy)return;busy=true;form.querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn();}catch(e){out.textContent=e.message;}finally{busy=false;form.querySelectorAll('button').forEach(b=>b.disabled=false);}}
function hint(){document.querySelector('#launch').textContent=form.elements.protocol.value==='text'?'CS2 启动参数：-netconport '+form.elements.port.value+'。使用本机 GOTV / Demo，并启用 RadarHUD 的 GSI 配置。':'使用 Workshop Tools 的 VConsole，端口和版本须与游戏一致。建议端口 29000、版本 212。';}
form.elements.protocol.onchange=hint;form.elements.port.oninput=hint;
form.onsubmit=e=>{e.preventDefault();action(async()=>{const config=Object.fromEntries([...new FormData(form)].map(([k,v])=>[k,k==='protocol'?v:Number(v)]));out.textContent='正在连接…';await req('tracker/config',config);const t=await req('tracker/connect',{});out.textContent=t.message+'\n'+(t.fresh?'GSI 已连接':'等待 GSI：请在 RadarHUD 页面配置 CS2');});};
document.querySelector('#disconnect').onclick=()=>action(async()=>{await req('tracker/disconnect',{});out.textContent='已断开 CS2 控制连接';});document.querySelector('#open').onclick=()=>action(async()=>{try{await req('window',{action:'open'});}catch{window.open('/director-bar.html');}});
action(async()=>{const d=await req('state'),t=d.tracker;for(const [k,v] of Object.entries(t.config||{}))if(form.elements[k])form.elements[k].value=v;hint();out.textContent=t.error||t.message||'未连接';});})();
